"""Random inputs for the balanced brackets problem: one line of text.

The balanced strings are grown with a stack, so they are balanced by
construction. The unbalanced ones are then made from those by an edit that
cannot leave them balanced: remove a bracket and the counts no longer agree;
splice in `([)]` after a complete string and the first closer meets the wrong
opener.
"""

OPENERS = "([{"
CLOSERS = {"(": ")", "[": "]", "{": "}"}
FILLER = "abcxyz0129 ;=+_"


def generate(rng, count):
    builders = (_balanced_case, _missing_bracket, _wrong_order, _with_filler)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, text, description=""):
    return {"name": name, "stdin": text + "\n", "description": description}


def _balanced(rng, pairs):
    text = []
    stack = []
    while pairs or stack:
        if pairs and (not stack or rng.random() < 0.6):
            opener = rng.choice(OPENERS)
            stack.append(opener)
            text.append(opener)
            pairs -= 1
        else:
            text.append(CLOSERS[stack.pop()])
    return "".join(text)


def _balanced_case(rng, index):
    return _case("balanced #%d" % index, _balanced(rng, rng.randint(3, 6)))


def _missing_bracket(rng, index):
    text = _balanced(rng, rng.randint(3, 6))
    cut = rng.randrange(len(text))
    return _case("one bracket removed #%d" % index, text[:cut] + text[cut + 1:],
                 "A balanced string with a single bracket deleted.")


def _wrong_order(rng, index):
    first, second = rng.sample(OPENERS, 2)
    crossed = first + second + CLOSERS[first] + CLOSERS[second]
    return _case("crossed, not nested #%d" % index,
                 _balanced(rng, rng.randint(1, 3)) + crossed,
                 "Every bracket is closed, but %s closes while %s is still "
                 "open. Counting is not enough." % (CLOSERS[first], second))


def _with_filler(rng, index):
    text = _balanced(rng, rng.randint(2, 5))
    noisy = []
    for char in text:
        noisy.append(char)
        if rng.random() < 0.5:
            noisy.append(rng.choice(FILLER))
    return _case("brackets among other text #%d" % index, "".join(noisy),
                 "Anything that is not a bracket is ignored.")
